<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??0);$p=null;$items=[];$msg='';if($id){$s=$db->prepare('SELECT * FROM proposals WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p)exit('Proposal not found.');$s=$db->prepare('SELECT * FROM proposal_items WHERE proposal_id=? ORDER BY sort_order,id');$s->execute([$id]);$items=$s->fetchAll();}if($_SERVER['REQUEST_METHOD']==='POST'){try{$db->beginTransaction();$lead=(int)$_POST['lead_id'];$title=trim((string)$_POST['title']);$currency=trim((string)$_POST['currency'])?:'NGN';$valid=$_POST['valid_until']?:null;$discount=max(0,(float)$_POST['discount']);$tax=max(0,(float)$_POST['tax']);$notes=trim((string)$_POST['notes']);$terms=trim((string)$_POST['terms']);$des=$_POST['item_description']??[];$qty=$_POST['item_quantity']??[];$price=$_POST['item_price']??[];$subtotal=0;$clean=[];foreach($des as $i=>$d){$d=trim((string)$d);if($d==='')continue;$q=max(0,(float)($qty[$i]??1));$pr=max(0,(float)($price[$i]??0));$amt=$q*$pr;$subtotal+=$amt;$clean[]=[$d,$q,$pr,$amt,$i];}$total=max(0,$subtotal-$discount+$tax);if($id){$s=$db->prepare('UPDATE proposals SET lead_id=?,title=?,currency=?,subtotal=?,discount=?,tax=?,total=?,valid_until=?,notes=?,terms=? WHERE id=?');$s->execute([$lead,$title,$currency,$subtotal,$discount,$tax,$total,$valid,$notes,$terms,$id]);$db->prepare('DELETE FROM proposal_items WHERE proposal_id=?')->execute([$id]);}else{$num='DWS-'.date('Ym').'-'.str_pad((string)random_int(1,9999),4,'0',STR_PAD_LEFT);$token=bin2hex(random_bytes(32));$s=$db->prepare('INSERT INTO proposals (lead_id,proposal_number,title,currency,subtotal,discount,tax,total,valid_until,notes,terms,public_token) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$lead,$num,$title,$currency,$subtotal,$discount,$tax,$total,$valid,$notes,$terms,$token]);$id=(int)$db->lastInsertId();}$ins=$db->prepare('INSERT INTO proposal_items (proposal_id,description,quantity,unit_price,amount,sort_order) VALUES (?,?,?,?,?,?)');foreach($clean as $x)$ins->execute([$id,$x[0],$x[1],$x[2],$x[3],$x[4]]);$db->commit();header('Location: proposal-form.php?id='.$id.'&saved=1');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$msg=$e->getMessage();}}$leads=$db->query("SELECT id,name,email FROM leads WHERE status NOT IN ('won','lost') ORDER BY name")->fetchAll();$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Proposal Editor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:1000px"><h1 class="h2 mb-4"><?=$id?'Edit':'New'?> Proposal</h1><?php if($msg):?><div class="alert alert-danger"><?=$esc($msg)?></div><?php endif;?><form method="post" class="card border-0 shadow-sm p-4"><div class="row g-3"><div class="col-md-6"><label class="form-label">Lead</label><select name="lead_id" class="form-select" required><?php foreach($leads as $l):?><option value="<?=$l['id']?>" <?=$p&&$p['lead_id']==$l['id']?'selected':''?>><?=$esc($l['name'])?> — <?=$esc($l['email'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Title</label><input name="title" class="form-control" required value="<?=$esc($p['title']??'Website & Digital Marketing Proposal')?>"></div><div class="col-md-3"><label class="form-label">Currency</label><input name="currency" class="form-control" value="<?=$esc($p['currency']??'NGN')?>"></div><div class="col-md-3"><label class="form-label">Valid Until</label><input type="date" name="valid_until" class="form-control" value="<?=$esc($p['valid_until']??date('Y-m-d',strtotime('+14 days')))?>"></div><div class="col-12"><label class="form-label">Items</label><div id="items"><?php if(!$items)$items=[['description'=>'Website Design & Development','quantity'=>1,'unit_price'=>0],['description'=>'Digital Marketing Setup','quantity'=>1,'unit_price'=>0]];foreach($items as $x):?><div class="row g-2 mb-2 item"><div class="col-md-6"><input name="item_description[]" class="form-control" placeholder="Description" value="<?=$esc($x['description'])?>"></div><div class="col-md-2"><input name="item_quantity[]" type="number" step="0.01" min="0" class="form-control" value="<?=$esc($x['quantity'])?>"></div><div class="col-md-3"><input name="item_price[]" type="number" step="0.01" min="0" class="form-control" value="<?=$esc($x['unit_price'])?>"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove">×</button></div></div><?php endforeach;?></div><button type="button" id="add" class="btn btn-sm btn-outline-dark">+ Add item</button></div><div class="col-md-6"><label class="form-label">Discount</label><input name="discount" type="number" step="0.01" min="0" class="form-control" value="<?=$esc($p['discount']??0)?>"></div><div class="col-md-6"><label class="form-label">Tax</label><input name="tax" type="number" step="0.01" min="0" class="form-control" value="<?=$esc($p['tax']??0)?>"></div><div class="col-md-6"><label class="form-label">Notes</label><textarea name="notes" class="form-control" rows="4"><?=$esc($p['notes']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Terms</label><textarea name="terms" class="form-control" rows="4"><?=$esc($p['terms']??'Payment terms and project commencement details will be confirmed upon acceptance.')?></textarea></div><div class="col-12"><button class="btn btn-dark">Save Proposal</button> <a href="proposals.php" class="btn btn-outline-secondary">Cancel</a></div></div></form></main><script>const items=document.getElementById('items');document.getElementById('add').onclick=()=>{items.insertAdjacentHTML('beforeend',`<div class="row g-2 mb-2 item"><div class="col-md-6"><input name="item_description[]" class="form-control" placeholder="Description"></div><div class="col-md-2"><input name="item_quantity[]" type="number" step="0.01" min="0" class="form-control" value="1"></div><div class="col-md-3"><input name="item_price[]" type="number" step="0.01" min="0" class="form-control" value="0"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger remove">×</button></div></div>`)};document.addEventListener('click',e=>{if(e.target.classList.contains('remove'))e.target.closest('.item').remove()});</script></body></html>